-- =====================================================================================
--  ARQUIVO 1:  CARGA DA AREA DE STAGING
--  Case: Pata Amiga - rede de petshops de SC  |  PostgreSQL 16
-- =====================================================================================
--  Rode este arquivo PRIMEIRO. Ele cria o banco e carrega as TRES tabelas de
--  origem como vieram dos sistemas: todas as colunas em texto, com os nomes
--  fora de snake_case e os dados sem tratamento.
--
--  ESTAS TABELAS NAO PODEM SER ALTERADAS: elas representam a origem. Nao use
--  UPDATE nem ALTER. Todo tratamento acontece nos INSERT das dimensoes e da
--  fato, nos arquivos 03 e 04.
--
--  Conecte-se ao banco "postgres" para rodar este arquivo (ele cria o
--  dw_pata_amiga e ja se conecta a ele com \c). No psql:
--      psql -U postgres -d postgres -f 01-carga-staging.sql
-- =====================================================================================

DROP DATABASE IF EXISTS dw_pata_amiga;
CREATE DATABASE dw_pata_amiga;
\c dw_pata_amiga

-- ----------------------------------------------------------------------------------
-- stg_pedido  (4044 linhas)
-- ----------------------------------------------------------------------------------
DROP TABLE IF EXISTS stg_pedido;
CREATE TABLE stg_pedido (
    "NumeroPedido"                VARCHAR(255),
    "DtHoraPedido"                VARCHAR(255),
    "DtHoraIntegracaoERP"         VARCHAR(255),
    "Loja-Nome"                   VARCHAR(255),
    "Cod Loja"                    VARCHAR(255),
    "Bairro Entrega"              VARCHAR(255),
    "CategoriaProduto"            VARCHAR(255),
    "FormaPagamento"              VARCHAR(255),
    "QTD.Itens"                   VARCHAR(255),
    "Qtd Unidades Devolvidas"     VARCHAR(255),
    "NrItensCancelados"           VARCHAR(255),
    "Peso Total (kg)"             VARCHAR(255),
    "ValorBrutoPedido(R$)"        VARCHAR(255),
    "Valor Desconto (R$)"         VARCHAR(255),
    "ValorLiquidoPedido(R$)"      VARCHAR(255),
    "HouveDesconto"               VARCHAR(255),
    "CanalPedido"                 VARCHAR(255),
    "Dt Separacao Estoque"        VARCHAR(255),
    "DtNotaFiscal"                VARCHAR(255),
    "Dt_Despacho_Transportadora"  VARCHAR(255),
    "DtEntregaCliente"            VARCHAR(255),
    "Valor Frete (R$)"            VARCHAR(255),
    "TransportadoraResponsavel"   VARCHAR(255),
    "SituacaoPedido"              VARCHAR(255),
    "OBS"                         VARCHAR(255)
);


-- ----------------------------------------------------------------------------------
-- stg_loja  (32 linhas)
-- ----------------------------------------------------------------------------------
DROP TABLE IF EXISTS stg_loja;
CREATE TABLE stg_loja (
    "CodLoja"              VARCHAR(255),
    "NomeLoja"             VARCHAR(255),
    "Cidade"               VARCHAR(255),
    "UF"                   VARCHAR(255),
    "Mesorregiao"          VARCHAR(255),
    "PopulacaoCidade"      VARCHAR(255),
    "AreaVenda_m2"         VARCHAR(255),
    "FaixaFranquia"        VARCHAR(255),
    "FormatoLoja"          VARCHAR(255),
    "CodCDReferencia"      VARCHAR(255),
    "DtUltimaAtualizacao"  VARCHAR(255)
);


-- ----------------------------------------------------------------------------------
-- stg_loja_praca  (48 linhas)
-- ----------------------------------------------------------------------------------
DROP TABLE IF EXISTS stg_loja_praca;
CREATE TABLE stg_loja_praca (
    "CodLoja"            VARCHAR(255),
    "NomeLoja"           VARCHAR(255),
    "CodPraca"           VARCHAR(255),
    "NomePraca"          VARCHAR(255),
    "Regional"           VARCHAR(255),
    "DomiciliosComPet"   VARCHAR(255),
    "PercentualPublico"  VARCHAR(255)
);


